CALL measure_loop
{"prompt": "What is 17 times 23? Reply with only the digits.", "max_tokens": 2048}

[TOOL RESULT measure_loop]
{
  "looped": false,
  "hit_cap": false,
  "repeated": false,
  "tokens": 24,
  "text_chars": 68,
  "text": "391"
